import com.roughpath.alpha.MarketStore;import org.json.*;
public class MarketStoreTest{
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{MarketStore.init(new android.content.Context());MarketStore.seed("{\"cash\":100,\"positions\":[],\"history\":[]}");long now=System.currentTimeMillis();MarketStore.tick(0,100,now-1000);String zero="{\"fee\":0,\"slip\":0,\"borrow\":0,\"funding\":0,\"liq\":90}";check(MarketStore.open(0,true,10,10,zero).equals("OK"),"Open failed");JSONObject b=new JSONObject(MarketStore.book());check(b.getDouble("cash")==90,"10 percent did not allocate $10");check(b.getJSONArray("positions").getJSONObject(0).getDouble("amount")==10,"Amount incorrect");MarketStore.tick(0,80,now);b=new JSONObject(MarketStore.book());check(b.getJSONArray("positions").length()==0,"Background tick did not liquidate");check(b.getJSONArray("history").getJSONObject(0).getString("status").equals("Liquidated"),"Liquidation not recorded");MarketStore.reset();check(new JSONObject(MarketStore.book()).getDouble("cash")==100,"Respawn failed");MarketStore.tick(0,100,System.currentTimeMillis());check(MarketStore.open(0,false,100,10,zero).equals("OK"),"100 percent order failed");check(new JSONObject(MarketStore.book()).getDouble("cash")==0,"100 percent leaves cash");MarketStore.merge(0,new JSONArray("[{\"t\":"+(now-120000)+",\"o\":100,\"h\":100,\"l\":90,\"c\":90}]"));MarketStore.tick(0,90,System.currentTimeMillis());JSONObject snap=new JSONObject(MarketStore.snapshot());check(snap.getJSONArray("candles").getJSONArray(0).length()>=2,"Background minute candles missing");String id=new JSONObject(MarketStore.book()).getJSONArray("positions").getJSONObject(0).getString("id");check(MarketStore.close(id).equals("OK"),"Close failed");check(new JSONObject(MarketStore.book()).getDouble("cash")>100,"Short profit missing");MarketStore.reset();check(new JSONObject(MarketStore.book()).getJSONArray("history").length()==0,"Respawn did not clear history");System.out.println("PASS: native percentage sizing, 100% sizing, background liquidation, paper settlement, candle collection across minutes, and $100 respawn.");}}
